            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .body("size()", is(1));
    }

    @Test
    @Order(3)
    public void testModeStillBlocksInvalidEmails() {
        String requestBody = """
            {
                "roomNumber": "301",
                "guestName": "Invalid Email Test",
                "guestEmail": "invalid.email",
                "guestCpf": "11122233344",
                "checkIn": "2027-05-10",
                "checkOut": "2027-05-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .body("size()", is(1))
            .body("[0].to", is("invalid.email"))
            .body("[0].status", is("BLOCKED"));
    }
}

